package com.bank.range;

import java.util.logging.*;

public class RangeQueryDemo {
    private static final Logger log = Logger.getLogger(RangeQueryDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // A closed month's daily net amounts (fixed / immutable)
        int[] dailyNet = {-2, 0, 3, -5, 2, -1};

        NumArray numArray = new NumArray(dailyNet);  // O(n) preprocessing

        log.info("sumRange(0,2) expect 1");
        log.info("Result -> " + numArray.sumRange(0, 2));  // -2+0+3 = 1

        log.info("sumRange(2,5) expect -1");
        log.info("Result -> " + numArray.sumRange(2, 5));  // 3-5+2-1 = -1

        log.info("sumRange(0,5) expect -3");
        log.info("Result -> " + numArray.sumRange(0, 5));  // whole month
    }
}

