class NumArray {
    private final long[] prefix;  // immutable snapshot of cumulative sums

    NumArray(int[] nums) {
        // Build once in the constructor. O(n). Long avoids overflow.
        prefix = new long[nums.length + 1];
        prefix[0] = 0;
        for (int i = 0; i < nums.length; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
    }

    // Inclusive range sum i..j in O(1).
    long sumRange(int i, int j) {
        return prefix[j + 1] - prefix[i];
    }
}

